/* STV — que exporta la libreria.
 *
 * -fvisibility=hidden deja que el compilador resuelva las llamadas internas
 * DIRECTO en vez de pasarlas por la tabla de indireccion (el @plt del perfil,
 * 1,23 % del hilo). Pero las funciones JNI estan declaradas como `extern "C"`
 * PELADAS, sin atributo de visibilidad, asi que la bandera tambien las escondio:
 * pasaron de 41 a 1 y la app dejo de arrancar. Verificado en el aparato.
 *
 * Este guion las devuelve sin tocar 41 declaraciones: Java las encuentra, y
 * todo lo demas queda interno.
 *
 * SOLO COMODINES, a proposito. Un nombre exacto que no exista es un ERROR de
 * enlace ("version script assignment failed: symbol not defined"), y JNI_OnUnload
 * no esta definido en este arbol. Los patrones no fallan si no hay coincidencia.
 */
{
  global:
    Java_*;
    JNI_*;
  local:
    *;
};
